 499→+// UninstallHooks removes Entire hooks from Cursor HooksFileName.
 500→+// Unknown top-level fields and hook types are preserved on round-trip.
 501→+func (c *CursorAgent) UninstallHooks() error {
 502→+	repoRoot, err := paths.RepoRoot()
 503→+	if err != nil {
 504→+		repoRoot = "."
 505→+	}
 506→+	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
 507→+	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 508→+	if err != nil {
 509→+		return nil //nolint:nilerr // No hooks file means nothing to uninstall
 510→+	}
 511→+
 512→+	var rawFile map[string]json.RawMessage
 513→+	if err := json.Unmarshal(data, &rawFile); err != nil {
 514→+		return fmt.Errorf("failed to parse "+HooksFileName+": %w", err)
 515→+	}
 516→+
 517→+	var rawHooks map[string]json.RawMessage
 518→+	if hooksRaw, ok := rawFile["hooks"]; ok {
 519→+		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 520→+			return fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
 521→+		}
 522→+	}
 523→+	if rawHooks == nil {
 524→+		rawHooks = make(map[string]json.RawMessage)
 525→+	}
 526→+
 527→+	// Parse only the hook types we manage
 528→+	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preToolUse, postToolUse []CursorHookEntry
 529→+	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
 530→+	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
 531→+	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
 532→+	parseCursorHookType(rawHooks, "stop", &stop)
 533→+	parseCursorHookType(rawHooks, "preToolUse", &preToolUse)
 534→+	parseCursorHookType(rawHooks, "postToolUse", &postToolUse)
 535→+
 536→+	// Remove Entire hooks from all hook types
 537→+	sessionStart = removeEntireHooks(sessionStart)
 538→+	sessionEnd = removeEntireHooks(sessionEnd)
 539→+	beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
 540→+	stop = removeEntireHooks(stop)
 541→+	preToolUse = removeEntireHooks(preToolUse)
 542→+	postToolUse = removeEntireHooks(postToolUse)
 543→+
 544→+	// Marshal modified hook types back into rawHooks
 545→+	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
 546→+	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
 547→+	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
 548→+	marshalCursorHookType(rawHooks, "stop", stop)
 549→+	marshalCursorHookType(rawHooks, "preToolUse", preToolUse)
 550→+	marshalCursorHookType(rawHooks, "postToolUse", postToolUse)
 551→+
 552→+	// Marshal hooks back (preserving unknown hook types)
 553→+	if len(rawHooks) > 0 {
 554→+		hooksJSON, err := json.Marshal(rawHooks)
 555→+		if err != nil {
 556→+			return fmt.Errorf("failed to marshal hooks: %w", err)
 557→+		}
 558→+		rawFile["hooks"] = hooksJSON
 559→+	} else {
 560→+		delete(rawFile, "hooks")
 561→+	}
 562→+
 563→+	// Write back
 564→+	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
 565→+	if err != nil {
 566→+		return fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
 567→+	}
 568→+
 569→+	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
 570→+		return fmt.Errorf("failed to write "+HooksFileName+": %w", err)
 571→+	}
 572→+	return nil
 573→+}
