 612→+// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
 613→+// Silently ignores parse errors (leaves target unchanged).
 614→+func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
 615→+	if data, ok := rawHooks[hookType]; ok {
 616→+		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
 617→+		json.Unmarshal(data, target)
 618→+	}
 619→+}
 620→+
 621→+// marshalCursorHookType marshals a hook type back into rawHooks.
 622→+// If the slice is empty, removes the key from rawHooks.
 623→+func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
 624→+	if len(entries) == 0 {
 625→+		delete(rawHooks, hookType)
 626→+		return
 627→+	}
 628→+	data, err := json.Marshal(entries)
 629→+	if err != nil {
 630→+		return // Silently ignore marshal errors (shouldn't happen)
 631→+	}
 632→+	rawHooks[hookType] = data
 633→+}
