 635→+// Helper functions for hook management
 636→+
 637→+func hookCommandExists(entries []CursorHookEntry, command string) bool {
 638→+	for _, entry := range entries {
 639→+		if entry.Command == command {
 640→+			return true
 641→+		}
 642→+	}
 643→+	return false
 644→+}
 645→+
 646→+func hookCommandExistsWithMatcher(entries []CursorHookEntry, matcher, command string) bool {
 647→+	for _, entry := range entries {
 648→+		if entry.Matcher == matcher && entry.Command == command {
 649→+			return true
 650→+		}
 651→+	}
 652→+	return false
 653→+}
 654→+
 655→+func isEntireHook(command string) bool {
 656→+	for _, prefix := range entireHookPrefixes {
 657→+		if strings.HasPrefix(command, prefix) {
 658→+			return true
 659→+		}
 660→+	}
 661→+	return false
 662→+}
 663→+
 664→+func hasEntireHook(entries []CursorHookEntry) bool {
 665→+	for _, entry := range entries {
 666→+		if isEntireHook(entry.Command) {
 667→+			return true
 668→+		}
 669→+	}
 670→+	return false
 671→+}
 672→+
 673→+func removeEntireHooks(entries []CursorHookEntry) []CursorHookEntry {
 674→+	result := make([]CursorHookEntry, 0, len(entries))
 675→+	for _, entry := range entries {
 676→+		if !isEntireHook(entry.Command) {
 677→+			result = append(result, entry)
 678→+		}
 679→+	}
 680→+	return result
 681→+}
