 53→	repoRoot, err := paths.RepoRoot()
 54→	if err != nil {
 55→		repoRoot = "."
 56→	}
 57→
 58→	cursorDir := filepath.Join(repoRoot, ".cursor")
 59→	if _, err := os.Stat(cursorDir); err == nil {
 60→		return true, nil
