223→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
224→
225→func sanitizePathForCursor(path string) string {
226→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
227→}
