 19→// Returns nil if the hook has no lifecycle significance.
 20→func (c *CursorAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
 21→	switch hookName {
 22→	case HookNameSessionStart:
 23→		return c.parseSessionStart(stdin)
 24→	case HookNameBeforeSubmitPrompt:
 25→		return c.parseTurnStart(stdin)
 26→	case HookNameStop:
 27→		return c.parseTurnEnd(stdin)
 28→	case HookNameSessionEnd:
 29→		return c.parseSessionEnd(stdin)
 30→	case HookNamePreTask:
 31→		return c.parseSubagentStart(stdin)
 32→	case HookNamePostTask:
 33→		return c.parseSubagentEnd(stdin)
 34→	case HookNamePostTodo:
 35→		// PostTodo is handled outside the generic dispatcher (incremental checkpoints).
 36→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 37→	default:
 38→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 39→	}
