 54→// InstallHooks installs Cursor hooks in .cursor/hooks.json.
 55→// If force is true, removes existing Entire hooks before installing.
 56→// Returns the number of hooks installed.
 57→// Unknown top-level fields and hook types are preserved on round-trip.
 58→func (c *CursorAgent) InstallHooks(localDev bool, force bool) (int, error) {
 59→	repoRoot, err := paths.RepoRoot()
 60→	if err != nil {
 61→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when RepoRoot() fails (tests run outside git repos)
 62→		if err != nil {
 63→			return 0, fmt.Errorf("failed to get current directory: %w", err)
 64→		}
 65→	}
 66→
 67→	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
 68→
 69→	// Use raw maps to preserve unknown fields on round-trip
 70→	var rawFile map[string]json.RawMessage
 71→	var rawHooks map[string]json.RawMessage
 72→
 73→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 74→	if readErr == nil {
 75→		if err := json.Unmarshal(existingData, &rawFile); err != nil {
 76→			return 0, fmt.Errorf("failed to parse existing "+HooksFileName+": %w", err)
 77→		}
 78→		if hooksRaw, ok := rawFile["hooks"]; ok {
 79→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 80→				return 0, fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
 81→			}
 82→		}
 83→	} else {
 84→		rawFile = map[string]json.RawMessage{
 85→			"version": json.RawMessage(`1`),
 86→		}
 87→	}
 88→
 89→	if rawHooks == nil {
 90→		rawHooks = make(map[string]json.RawMessage)
 91→	}
 92→
 93→	// Parse only the hook types we manage
 94→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preToolUse, postToolUse []CursorHookEntry
 95→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
 96→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
 97→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
 98→	parseCursorHookType(rawHooks, "stop", &stop)
 99→	parseCursorHookType(rawHooks, "preToolUse", &preToolUse)
100→	parseCursorHookType(rawHooks, "postToolUse", &postToolUse)
101→
102→	// If force is true, remove all existing Entire hooks first
103→	if force {
104→		sessionStart = removeEntireHooks(sessionStart)
105→		sessionEnd = removeEntireHooks(sessionEnd)
106→		beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
107→		stop = removeEntireHooks(stop)
108→		preToolUse = removeEntireHooks(preToolUse)
109→		postToolUse = removeEntireHooks(postToolUse)
110→	}
111→
112→	// Define hook commands
113→	var cmdPrefix string
114→	if localDev {
115→		cmdPrefix = "go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go hooks cursor "
116→	} else {
117→		cmdPrefix = "entire hooks cursor "
118→	}
119→
120→	sessionStartCmd := cmdPrefix + "session-start"
121→	sessionEndCmd := cmdPrefix + "session-end"
122→	beforeSubmitPromptCmd := cmdPrefix + "before-submit-prompt"
123→	stopCmd := cmdPrefix + "stop"
124→	preTaskCmd := cmdPrefix + "pre-task"
125→	postTaskCmd := cmdPrefix + "post-task"
126→	postTodoCmd := cmdPrefix + "post-todo"
127→
128→	count := 0
129→
130→	// Add hooks if they don't exist
131→	if !hookCommandExists(sessionStart, sessionStartCmd) {
132→		sessionStart = append(sessionStart, CursorHookEntry{Command: sessionStartCmd})
133→		count++
134→	}
135→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
136→		sessionEnd = append(sessionEnd, CursorHookEntry{Command: sessionEndCmd})
137→		count++
138→	}
139→	if !hookCommandExists(beforeSubmitPrompt, beforeSubmitPromptCmd) {
140→		beforeSubmitPrompt = append(beforeSubmitPrompt, CursorHookEntry{Command: beforeSubmitPromptCmd})
141→		count++
142→	}
143→	if !hookCommandExists(stop, stopCmd) {
144→		stop = append(stop, CursorHookEntry{Command: stopCmd})
145→		count++
146→	}
147→	if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
148→		preToolUse = append(preToolUse, CursorHookEntry{Command: preTaskCmd, Matcher: "Task"})
149→		count++
150→	}
151→	if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
152→		postToolUse = append(postToolUse, CursorHookEntry{Command: postTaskCmd, Matcher: "Task"})
153→		count++
154→	}
155→	if !hookCommandExistsWithMatcher(postToolUse, "TodoWrite", postTodoCmd) {
156→		postToolUse = append(postToolUse, CursorHookEntry{Command: postTodoCmd, Matcher: "TodoWrite"})
157→		count++
158→	}
159→
160→	if count == 0 {
161→		return 0, nil
162→	}
163→
164→	// Marshal modified hook types back into rawHooks
165→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
166→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
167→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
168→	marshalCursorHookType(rawHooks, "stop", stop)
169→	marshalCursorHookType(rawHooks, "preToolUse", preToolUse)
170→	marshalCursorHookType(rawHooks, "postToolUse", postToolUse)
171→
172→	// Marshal hooks and update raw file
173→	hooksJSON, err := json.Marshal(rawHooks)
174→	if err != nil {
175→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
176→	}
177→	rawFile["hooks"] = hooksJSON
178→
179→	// Write to file
180→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
181→		return 0, fmt.Errorf("failed to create .cursor directory: %w", err)
182→	}
183→
184→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
185→	if err != nil {
186→		return 0, fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
187→	}
188→
189→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
190→		return 0, fmt.Errorf("failed to write "+HooksFileName+": %w", err)
191→	}
192→
193→	return count, nil
194→}
