196→// UninstallHooks removes Entire hooks from Cursor HooksFileName.
197→// Unknown top-level fields and hook types are preserved on round-trip.
198→func (c *CursorAgent) UninstallHooks() error {
199→	repoRoot, err := paths.RepoRoot()
200→	if err != nil {
201→		repoRoot = "."
202→	}
203→	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
204→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
205→	if err != nil {
206→		return nil //nolint:nilerr // No hooks file means nothing to uninstall
207→	}
208→
209→	var rawFile map[string]json.RawMessage
210→	if err := json.Unmarshal(data, &rawFile); err != nil {
211→		return fmt.Errorf("failed to parse "+HooksFileName+": %w", err)
212→	}
213→
214→	var rawHooks map[string]json.RawMessage
215→	if hooksRaw, ok := rawFile["hooks"]; ok {
216→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
217→			return fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
218→		}
219→	}
220→	if rawHooks == nil {
221→		rawHooks = make(map[string]json.RawMessage)
222→	}
223→
224→	// Parse only the hook types we manage
225→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preToolUse, postToolUse []CursorHookEntry
226→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
227→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
228→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
229→	parseCursorHookType(rawHooks, "stop", &stop)
230→	parseCursorHookType(rawHooks, "preToolUse", &preToolUse)
231→	parseCursorHookType(rawHooks, "postToolUse", &postToolUse)
232→
233→	// Remove Entire hooks from all hook types
234→	sessionStart = removeEntireHooks(sessionStart)
235→	sessionEnd = removeEntireHooks(sessionEnd)
236→	beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
237→	stop = removeEntireHooks(stop)
238→	preToolUse = removeEntireHooks(preToolUse)
239→	postToolUse = removeEntireHooks(postToolUse)
240→
241→	// Marshal modified hook types back into rawHooks
242→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
243→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
244→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
245→	marshalCursorHookType(rawHooks, "stop", stop)
246→	marshalCursorHookType(rawHooks, "preToolUse", preToolUse)
247→	marshalCursorHookType(rawHooks, "postToolUse", postToolUse)
248→
249→	// Marshal hooks back (preserving unknown hook types)
250→	if len(rawHooks) > 0 {
251→		hooksJSON, err := json.Marshal(rawHooks)
252→		if err != nil {
253→			return fmt.Errorf("failed to marshal hooks: %w", err)
254→		}
255→		rawFile["hooks"] = hooksJSON
256→	} else {
257→		delete(rawFile, "hooks")
258→	}
259→
260→	// Write back
261→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
262→	if err != nil {
263→		return fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
264→	}
265→
266→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
267→		return fmt.Errorf("failed to write "+HooksFileName+": %w", err)
268→	}
269→	return nil
270→}
