272→// AreHooksInstalled checks if Entire hooks are installed.
273→func (c *CursorAgent) AreHooksInstalled() bool {
274→	repoRoot, err := paths.RepoRoot()
275→	if err != nil {
276→		repoRoot = "."
277→	}
278→	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
279→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
280→	if err != nil {
281→		return false
282→	}
283→
284→	var hooksFile CursorHooksFile
285→	if err := json.Unmarshal(data, &hooksFile); err != nil {
286→		return false
287→	}
288→
289→	return hasEntireHook(hooksFile.Hooks.SessionStart) ||
290→		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
291→		hasEntireHook(hooksFile.Hooks.BeforeSubmitPrompt) ||
292→		hasEntireHook(hooksFile.Hooks.Stop) ||
293→		hasEntireHook(hooksFile.Hooks.PreToolUse) ||
294→		hasEntireHook(hooksFile.Hooks.PostToolUse)
295→}
