309→// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
310→// Silently ignores parse errors (leaves target unchanged).
311→func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
312→	if data, ok := rawHooks[hookType]; ok {
313→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
314→		json.Unmarshal(data, target)
315→	}
316→}
317→
318→// marshalCursorHookType marshals a hook type back into rawHooks.
319→// If the slice is empty, removes the key from rawHooks.
320→func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
321→	if len(entries) == 0 {
322→		delete(rawHooks, hookType)
323→		return
324→	}
325→	data, err := json.Marshal(entries)
326→	if err != nil {
327→		return // Silently ignore marshal errors (shouldn't happen)
328→	}
329→	rawHooks[hookType] = data
330→}
