352→func TestChunkTranscript_LargeContent(t *testing.T) {
353→	ag := &GeminiCLIAgent{}
354→
355→	// Create a transcript with many messages that exceeds maxSize
356→	var messages []GeminiMessage
357→	for i := range 100 {
358→		messages = append(messages, GeminiMessage{
359→			Type:    "user",
360→			Content: fmt.Sprintf("message %d with some content to make it larger: %s", i, strings.Repeat("x", 500)),
361→		})
362→	}
363→
364→	transcript := GeminiTranscript{Messages: messages}
365→	content, err := json.Marshal(transcript)
366→	if err != nil {
367→		t.Fatalf("Failed to marshal test transcript: %v", err)
368→	}
369→
370→	// Use a small maxSize to force chunking
371→	maxSize := 5000
372→	chunks, err := ag.ChunkTranscript(content, maxSize)
373→	if err != nil {
374→		t.Fatalf("ChunkTranscript() error = %v", err)
375→	}
376→
377→	if len(chunks) < 2 {
378→		t.Errorf("Expected at least 2 chunks for large content, got %d", len(chunks))
379→	}
380→
381→	// Verify each chunk is valid JSON with messages array
382→	for i, chunk := range chunks {
383→		var parsed GeminiTranscript
384→		if err := json.Unmarshal(chunk, &parsed); err != nil {
385→			t.Errorf("Chunk %d is not valid Gemini JSON: %v", i, err)
386→		}
387→		if len(parsed.Messages) == 0 {
388→			t.Errorf("Chunk %d has no messages", i)
389→		}
390→	}
391→
392→	// Verify reassembly gives back all messages
393→	reassembled, err := ag.ReassembleTranscript(chunks)
394→	if err != nil {
395→		t.Fatalf("ReassembleTranscript() error = %v", err)
396→	}
397→
398→	var result GeminiTranscript
399→	if err := json.Unmarshal(reassembled, &result); err != nil {
400→		t.Fatalf("Failed to unmarshal reassembled content: %v", err)
401→	}
402→
403→	if len(result.Messages) != len(messages) {
404→		t.Errorf("Reassembled message count = %d, want %d", len(result.Messages), len(messages))
