442→func TestChunkTranscript_RoundTrip(t *testing.T) {
443→	ag := &GeminiCLIAgent{}
444→
445→	// Create a realistic transcript
446→	original := GeminiTranscript{
447→		Messages: []GeminiMessage{
448→			{Type: "user", Content: "Write a hello world program"},
449→			{Type: "gemini", Content: "Sure, here's a hello world program:", ToolCalls: []GeminiToolCall{
450→				{ID: "1", Name: "write_file", Args: map[string]interface{}{"path": "main.go", "content": "package main\n\nfunc main() {\n\tprintln(\"Hello, World!\")\n}"}},
451→			}},
452→			{Type: "user", Content: "Now add a function"},
453→			{Type: "gemini", Content: "I'll add a greet function:", ToolCalls: []GeminiToolCall{
454→				{ID: "2", Name: "edit_file", Args: map[string]interface{}{"path": "main.go"}},
455→			}},
456→		},
457→	}
458→
459→	content, err := json.Marshal(original)
460→	if err != nil {
461→		t.Fatalf("Failed to marshal original: %v", err)
462→	}
463→
464→	// Use small maxSize to force chunking
465→	maxSize := 200
466→	chunks, err := ag.ChunkTranscript(content, maxSize)
467→	if err != nil {
468→		t.Fatalf("ChunkTranscript() error = %v", err)
469→	}
470→
471→	reassembled, err := ag.ReassembleTranscript(chunks)
472→	if err != nil {
473→		t.Fatalf("ReassembleTranscript() error = %v", err)
474→	}
475→
476→	var result GeminiTranscript
477→	if err := json.Unmarshal(reassembled, &result); err != nil {
478→		t.Fatalf("Failed to unmarshal reassembled: %v", err)
479→	}
480→
481→	if len(result.Messages) != len(original.Messages) {
482→		t.Fatalf("Message count mismatch: got %d, want %d", len(result.Messages), len(original.Messages))
483→	}
484→
485→	for i, msg := range result.Messages {
486→		if msg.Type != original.Messages[i].Type {
487→			t.Errorf("Message %d type = %q, want %q", i, msg.Type, original.Messages[i].Type)
488→		}
489→		if msg.Content != original.Messages[i].Content {
490→			t.Errorf("Message %d content mismatch", i)
