 56→
 57→func (c *CursorAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
 58→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
 59→	if err != nil {
 60→		return nil, err
 61→	}
 62→	return &agent.Event{
 63→		Type:       agent.SessionStart,
 64→		SessionID:  raw.getSessionID(),
